 public void PreviewMageScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;Check(catalog.Deckable(catalog.Pool("classic-2014")).Where(c=>c.CardClass=="MAGE").All(matchRules.Supports),"Mage 25 of 25 enabled");VerifyMageTcp(folder);File.WriteAllText(Path.Combine(folder,"mage-verification.txt"),"PASS: "+(checks-before)+" focused Mage assertions; free secret, spell triggers, adjacent freeze, private generated hand and real loopback TCP.");}
 void VerifyMageTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Mage peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host mulligan reaches guest");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Both mulligans complete");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}var wyrm=g.Summon(0,"VAN_NEW1_012");g.Summon(0,"VAN_EX1_559");var enemy=Enumerable.Range(0,3).Select(n=>g.Summon(1,"VAN_CS2_182")).ToArray();int kirin=Inject(g,"EX1_612"),secret=Inject(g,"EX1_289"),cone=Inject(g,"EX1_275");PublishLan();BeginCard(kirin);ClickEmptySlot(0,2);PumpLan(()=>guest.match.Players[0].FreeSecretThisTurn,"Host free secret offer synchronizes");Check(match.HandCost(0,match.Players[0].Hand.Single(h=>h.Id==secret))==0,"Host hand displays free secret");BeginCard(secret);PumpLan(()=>guest.match.Players[0].SecretCount==1&&!guest.match.Players[0].FreeSecretThisTurn,"Host secret consumes offer");Check(guest.match.Players[0].Hand.Count==0&&g.AttackValue(wyrm)==2,"Secret triggers Wyrm while generated hand remains private");BeginCard(cone);ClickMatchTarget(new MatchTarget(1,enemy[1].Id));PumpLan(()=>guest.match.Players[1].Board.All(u=>u.Frozen&&u.Health==4),"Host cone target and neighbors freeze over TCP");Check(g.Players[0].Hand.Count==2&&guest.match.Players[0].HandCount==2&&guest.match.Players[0].Hand.Count==0,"Both Antonidas Fireballs counted without exposing hand");Render(Path.Combine(folder,"130-mage-cone-codex.png"));DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest turn starts");
  g.Players[1].Hand.Clear();g.Players[1].Mana=10;g.Players[1].Board.Clear();var guestWyrm=g.Summon(1,"VAN_NEW1_012");g.Summon(1,"VAN_EX1_559");int guestKirin=Inject(g,"EX1_612",1),guestSecret=Inject(g,"EX1_294",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==guestKirin),"Guest fixtures reach private hand");guest.BeginCard(guestKirin);guest.ClickEmptySlot(1,2);PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].FreeSecretThisTurn,"Guest Kirin resolves on host authority");Check(guest.match.HandCost(1,guest.match.Players[1].Hand.Single(h=>h.Id==guestSecret))==0,"Guest receives correct zero cost");guest.BeginCard(guestSecret);PumpLan(()=>!guest.lanWaiting&&g.Players[1].SecretCount==1,"Guest free secret hangs on authority");Check(!g.Players[1].FreeSecretThisTurn&&g.AttackValue(guestWyrm)==2&&guest.match.Players[1].Hand.Single().CardId=="VAN_CS2_029"&&LanProtocol.View(g,0,"mage",1).Players[1].Hand.Length==0,"Guest generated spell and offer stay synchronized and private");
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
